import{_ as p,a0 as l,w as i,s,I as o,x as e,a1 as a,A as r,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"一個可以顯示Linux命令運行進度的偉大工具 | LCTT x X-CMD","titleTemplate":false,"description":"一個可以顯示Linux命令運行進度的偉大工具 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一個可以顯示Linux命令運行進度的偉大工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一個可以顯示Linux命令運行進度的偉大工具 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA","title":"一個可以顯示Linux命令運行進度的偉大工具","tag":"201501","desc":""},"relativePath":"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA.md","filePath":"[post].md"}'),c={name:"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA.md"};function m(u,t,g,x,h,v){const n=l("Link");return i(),s("div",null,[t[16]||(t[16]=o("h1",{id:"一個可以顯示linux命令運行進度的偉大工具",tabindex:"-1"},[e("一個可以顯示Linux命令運行進度的偉大工具 "),o("a",{class:"header-anchor",href:"#一個可以顯示linux命令運行進度的偉大工具","aria-label":"Permalink to “一個可以顯示Linux命令運行進度的偉大工具”"},"​")],-1)),t[17]||(t[17]=o("p",null,[e("Coreutils Viewer（"),o("strong",null,"cv"),e("）是一個簡單的程序，它可以用於顯示任何核心組件命令（如：cp、mv、dd、tar、gzip、gunzip、cat、grep、fgrep、egrep、cut、sort、xz、exiting）的進度。它使用文件描述信息來確定一個命令的進度，比如cp命令。"),o("strong",null,"cv"),e("之美在於，它能夠和其它Linux命令一起使用，比如你所知道的watch以及I/O重定向命令。這樣，你就可以在腳本中使用，或者你能想到的所有方式，別讓你的想像力束縛住你。")],-1)),t[18]||(t[18]=o("h3",{id:"安裝",tabindex:"-1"},[e("安裝 "),o("a",{class:"header-anchor",href:"#安裝","aria-label":"Permalink to “安裝”"},"​")],-1)),o("p",null,[t[1]||(t[1]=e("你可以從cv的",-1)),a(n,{href:"http://github.com/Xfennec/cv"},{default:r(()=>[...t[0]||(t[0]=[e("github倉庫那兒",-1)])]),_:1}),t[2]||(t[2]=e("下載所需的源文件。把zip文件下載下來後，將它解壓縮，然後進入到解壓後的文件夾。",-1))]),t[19]||(t[19]=d(`<p>該程序需要<strong>ncurses library</strong>。如果你已經在你的Linux系統中安裝了ncurses，那麼cv的安裝過程對你而言就是那麼的輕鬆寫意。</p><p>通過以下兩個簡單步驟來進行編譯和安裝吧。</p><pre><code>$ make
$ sudo make install
</code></pre><h3 id="運行cv" tabindex="-1">運行cv <a class="header-anchor" href="#運行cv" aria-label="Permalink to “運行cv”">​</a></h3><p>要運行cv，只需要想其它程序一樣，在命令列輸入此命令即可。如果你沒有執行make install，而選擇從當前目錄中去運行，那麼你可以運行以下命令：</p><pre><code>$ ./cv
</code></pre><p>否則，就運行以下命令吧。</p><pre><code>$ cv
</code></pre><p>如果沒有核心組件命令在運行，那麼cv程序會退出，並告訴你：沒有核心組件命令在運行。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-no-command.png" alt="cv no command"></p><p>要有效使用該程序，請在你係統上運行某個核心組件程序。在本例中，我們將使用<strong>cp</strong>命令。</p><p>當拷貝一個打文件時，你就可以看到當前進度了，以百分比顯示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-default.png" alt="cv default"></p><h3 id="添加選項到-cv" tabindex="-1">添加選項到 cv <a class="header-anchor" href="#添加選項到-cv" aria-label="Permalink to “添加選項到 cv”">​</a></h3><p>你也可以添加幾個選項到cv命令，就像其它命令一樣。一個有用的選項是讓你瞭解到拷貝或移動大文件時的預計剩餘時間。</p><p>添加<strong>-w</strong>選項，它就會幫你顯示預計的剩餘時間。</p><pre><code>$ cv -w
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-estimated-throughput.png" alt="cv estimated throughput"></p><p>試着添加更多的命令選項吧。像下面這樣添加其它選項：</p><pre><code>$ cv -wq
</code></pre><h3 id="cv-和-watch-命令" tabindex="-1">cv 和 watch 命令 <a class="header-anchor" href="#cv-和-watch-命令" aria-label="Permalink to “cv 和 watch 命令”">​</a></h3><p>watch是一個用於週期性運行程序並顯示輸出結果的程序。有時候，你可能想要持續看看命令運行狀況而不想將 cv 的結果存儲到日誌文件中。在這種情況下，watch就會派上用場了，它可以和cv一起使用。</p><pre><code>$ watch cv -qw
</code></pre><p>該命令將會顯示所有運行着的核心組件命令的實例。它也會顯示進度和預計完成時間。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-and-watch-e1416519384265.png" alt="cv and watch"></p><h3 id="在日誌文件中查看輸出結果" tabindex="-1">在日誌文件中查看輸出結果 <a class="header-anchor" href="#在日誌文件中查看輸出結果" aria-label="Permalink to “在日誌文件中查看輸出結果”">​</a></h3><p>正如其所承諾的那樣，你可以使用cv來重定向它的輸出結果到一個日誌文件。這功能在命令運行太快而看不到任何有意義的內容時特別有用。</p><p>要在日誌文件中查看進度，你僅僅需要重定向輸出結果，就像下面這樣。</p><pre><code>$ cv -w &gt;&gt; log.txt
</code></pre><p>要查看該命令的輸出結果，請用你喜愛的文本編輯器打開日誌文件，也可以用cat命令，就像下面這樣：</p><pre><code>$ cat log.txt
</code></pre><h3 id="獲得幫助" tabindex="-1">獲得幫助 <a class="header-anchor" href="#獲得幫助" aria-label="Permalink to “獲得幫助”">​</a></h3><p>如果你在任何地方受到阻礙，你總是可以通過查閲手冊頁或使用help選項來獲取幫助信息。 要獲取幫助信息，可以使用帶<strong>-h</strong>選項的cv命令。</p><pre><code>$ cv -h
</code></pre><p>如果需要更多詳細信息，那麼手冊頁是個很不錯的地方。</p><pre><code>$ man cv
</code></pre><p>但是，要獲取上述手冊頁，你必須執行make install來安裝cv。</p><p>耶！現在，你的Linux工具箱中又多了個偉大的工具。 你學會麼？親自去試試吧~</p><hr>`,39)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://linoxide.com/linux-command/tool-show-command-progress/"},{default:r(()=>[...t[3]||(t[3]=[e("http://linoxide.com/linux-command/tool-show-command-progress/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://linoxide.com/author/allan/"},{default:r(()=>[...t[5]||(t[5]=[e("Allan Mbugua",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),a(n,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[6]||(t[6]=[e("GOLinux",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const L=p(c,[["render",m]]);export{w as __pageData,L as default};
